SET session_replication_role = replica;

TRUNCATE TABLE commissions, transactions, commission_overrides, sub_agent_sales, bot_texts, rank_titles, game_configs, platform_settings, sub_agent_tiers, wallets, bots, users RESTART IDENTITY CASCADE;


SET session_replication_role = DEFAULT;
SELECT setval('users_id_seq', (SELECT MAX(id) FROM users), true);
SELECT setval('wallets_id_seq', (SELECT MAX(id) FROM wallets), true);
SELECT setval('bots_id_seq', (SELECT MAX(id) FROM bots), true);
SELECT setval('transactions_id_seq', (SELECT MAX(id) FROM transactions), true);
SELECT setval('commissions_id_seq', (SELECT MAX(id) FROM commissions), true);
SELECT setval('game_configs_id_seq', (SELECT MAX(id) FROM game_configs), true);
SELECT setval('bot_texts_id_seq', (SELECT MAX(id) FROM bot_texts), true);
SELECT setval('rank_titles_id_seq', (SELECT MAX(id) FROM rank_titles), true);
SELECT 'Done! Users: ' || count(*)::text FROM users;
